import java.io.*; import java.math.*; import java.security.*; import java.text.*; import java.util.*; import java.util.concurrent.*; import java.util.regex.*; class Result { public static int pickingNumbers(List<Integer> a) { int[] counts = new int[101]; for (int num : a) { counts[num]++; } int maxLen = 0; for (int i = 1; i < 100; i++) { int currentLen = counts[i] + counts[i + 1]; if (currentLen > maxLen) { maxLen = currentLen; } } return maxLen; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH"))); int n = Integer.parseInt(bufferedReader.readLine().trim()); String[] aTemp = bufferedReader.readLine().replaceAll("\\s+$", "").split(" "); List<Integer> a = new ArrayList<>(); for (int i = 0; i < n; i++) { int aItem = Integer.parseInt(aTemp[i]); a.add(aItem); } int result = Result.pickingNumbers(a); bufferedWriter.write(String.valueOf(result)); bufferedWriter.newLine(); bufferedReader.close(); bufferedWriter.close(); } }